BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('HBSE-112-1-020','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第2條（老人指年滿六十五歲以上之人），最後修正公布日：第2條 2007-01-31，本題考試日 2023-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP104-1-18','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考行政院「友善關懷老人服務方案」第二期計畫目標，非老人福利法條文內容，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP104-1-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考世界衛生組織高齡友善城市之活躍老化概念，非老人福利法條文內容，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP104-1-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考老人福利法第12條；2015-12-09 修正僅增訂不得有設籍時間限制並將不得扣押規定移至第12條之1，生活津貼排除已接受收容安置者、特別照顧津貼由照顧者申請之規定未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP104-2-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考老人福利法第16條；考試時原則為全人照顧、在地老化及多元連續服務，2015-12-09 修正增列健康促進、延緩失能、社會參與，選項中「現金給付」「高齡友善」仍非法定原則，答案①④⑤不變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP105-2-13','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考1991年聯合國老人綱領（聯合國老人綱領五大原則），非老人福利法條文內容，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP105-2-23','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考老人福利法第34條、第36條。考試時第34條規定機構標準由中央主管機關「會同」中央目的事業主管機關定之（官方答案B：財團法人登記期限為三個月）；2020-05-27 修正後改為「會商」，選項(A)用語已與現行條文不同。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP105-2-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第6條、第9條、第10條（經費來源、代表比例、生活狀況調查），最後修正公布日：第6條 2007-01-31、第9條 2007-01-31、第10條 2007-01-31，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP106-1-22','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考老人福利法第41條第3項之償還義務人。考試時條文為「直系血親卑親屬或依契約有扶養義務者」（官方答案A）；2020-05-27 修正後改為「老人、老人之配偶、直系血親卑親屬或依契約負照顧義務者」，依現行條文配偶亦屬之。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP106-1-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第11條（老人經濟安全保障方式），最後修正公布日：第11條 2007-01-31，本題考試日 2017-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP106-2-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第10條（每五年老人生活狀況調查，最後修正公布日 2007-01-31）、兒童及少年福利與權益保障法第13條（每四年兒少現況調查；2019-04-24 修正僅增訂兒童死亡原因回溯分析，每四年之規定考試時即已存在）、身心障礙者權益保障法第11條（每五年調查、每十年人口普查，最後修正公布日 2007-07-11），考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP106-2-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第11條（老人經濟安全保障方式），最後修正公布日：第11條 2007-01-31，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP106-2-29','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第16條（老人照顧服務原則），最後修正公布日：第16條 2015-12-09，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP107-1-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考老人福利法第12條、第12條之1、第14條（經濟安全保障），最後修正公布日：第12條 2015-12-09、第12條之1 2015-12-09、第14條 2015-12-09，本題考試日 2018-02-03 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP107-1-22','verified_current',$swsi$考